const STAGE2_LABEL = "stage2_skill_models";
const STAGE3_LABEL = "stage3_tier_groups";
const STAGE4_LABEL = "stage4_legacy_shape";
const STAGE5_LABEL = "stage5_framework_default";
const STAGE6_LABEL = "stage6_prefer_pro_overlay";

// Error codes — pinned by schema enum.
const ERR_TIER_NO_MAPPING         = "[TIER-NO-MAPPING]";
const ERR_OVERRIDE_UNKNOWN        = "[OVERRIDE-UNKNOWN-MODEL]";
const ERR_EXTRA_OVERRIDE_CONFLICT = "[MODEL-EXTRA-OVERRIDE-CONFLICT]";
const ERR_NO_RESOLUTION           = "[NO-RESOLUTION]";
const ERR_INPUT_CONTROL_BYTE      = "[INPUT-CONTROL-BYTE]";

// Tier names recognized as tier-tags. Per IMP-007, when a `skill_models.<X>.<Y>`
// value matches one of these AND also exists in `model_aliases_extra`, the
// tier-tag interpretation wins.
const TIER_NAMES: ReadonlySet<string> = new Set([
"cheap",
"max",
"mid",
"tiny",
]);

// Control-byte regex — mirrors Python's _CTRL_BYTE_RE. Matches C0 control
// bytes other than tab (0x09) and newline (0x0A). Used to reject inputs
// before the resolver sees them (cypherpunk HIGH-2). The pattern source is
// extracted from the canonical Python regex; both runtimes' regex engines
// (Python `re` + JS RegExp) interpret the char class identically.
const CTRL_BYTE_RE = /[\x00-\x08\x0B-\x1F]/;

// --- Helpers --------------------------------------------------------------

/**
 * cypherpunk CRIT-1 (sprint-1D PR #735): JS `key in obj` walks Object.prototype.
 * Use Object.create(null) for parsed maps + hasOwn for membership.
 */
function hasKey(obj: Record<string, unknown> | null | undefined, key: string): boolean {
    if (obj === null || obj === undefined) return false;
    return Object.prototype.hasOwnProperty.call(obj, key);
